urlset:
{% for page in site.pages %}

    https://john.colagioia.net/blog{{page.url}}
    {{site.time | date: '%Y-%m-%d' }}
    daily
    0.5

{% endfor %}

{% for post in site.posts %}

    https://john.colagioia.net/blog{{post.url}}
    {{site.time | date: '%Y-%m-%d' }}
    daily
    0.75

{% endfor %}
